#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main() {
    char expr[] = "3 + 4 * 2";
    for (int i = 0; i < strlen(expr); i++) {
        if (isspace(expr[i])) continue;
        if (isdigit(expr[i])) {
            int num = 0;
            while (i < strlen(expr) && isdigit(expr[i])) {
                num = num * 10 + (expr[i] - '0');
                i++;
            }
            i--;
            printf("NUMBER: %d\n", num);
        } else {
            printf("OPERATOR: %c\n", expr[i]);
        }
    }
    return 0;
}
